## Convert Cents to Dollars Using `array_map`

### Basic Implementation

```php
<?php

/**
 * Converts an array of prices from cents to dollars.
 *
 * @param int[] $prices Array of prices in cents
 * @return float[] Array of prices in dollars
 */
function convertCentsToDollars(array $prices): array
{
    return array_map(fn(int $cents): float => $cents / 100, $prices);
}
```

### Usage Examples

```php
<?php

// Basic usage
$pricesInCents = [199, 999, 1499, 2999, 10000];
$pricesInDollars = convertCentsToDollars($pricesInCents);

print_r($pricesInDollars);
/*
Array
(
    [0] => 1.99
    [1] => 9.99
    [2] => 14.99
    [3] => 29.99
    [4] => 100
)
*/

// Format as currency strings
$formatted = array_map(
    fn(float $price): string => '$' . number_format($price, 2),
    $pricesInDollars
);

print_r($formatted);
/*
Array
(
    [0] => $1.99
    [1] => $9.99
    [2] => $14.99
    [3] => $29.99
    [4] => $100.00
)
*/
```

### Extended Version with Formatting

```php
<?php

/**
 * Converts an array of prices from cents to formatted dollar strings.
 *
 * @param int[]  $prices    Array of prices in cents
 * @param string $currency  Currency symbol (default: '$')
 * @param int    $decimals  Number of decimal places (default: 2)
 * @return string[] Array of formatted price strings
 */
function convertCentsToDollarStrings(
    array $prices,
    string $currency = '$',
    int $decimals = 2
): array {
    return array_map(
        fn(int $cents): string => $currency . number_format($cents / 100, $decimals),
        $prices
    );
}

// Usage
$prices = [0, 99, 1050, 29999, 100000];

print_r(convertCentsToDollarStrings($prices));
/*
Array
