---

### Extended Version with Validation & Flexibility

```php
<?php

/**
 * Sorts an array of products by price.
 *
 * @param array  $products  Array of products (each with a 'price' key)
 * @param string $direction Sort direction: 'asc' or 'desc'
 * @return array Sorted array of products
 * @throws InvalidArgumentException If a product is missing the 'price' key
 */
function sortProductsByPrice(array $products, string $direction = 'asc'): array
{
    if (empty($products)) {
        return [];
    }

    // Validate that all products have a 'price' key
    foreach ($products as $index => $product) {
        if (!isset($product['price'])) {
            throw new InvalidArgumentException(
                "Product at index {$index} is missing the 'price' key."
            );
        }

        if (!is_numeric($product['price'])) {
            throw new InvalidArgumentException(
                "Product at index {$index} has a non-numeric price: '{$product['price']}'."
            );
        }
    }

    $multiplier = strtolower($direction) === 'desc' ? -1 : 1;

    usort($products, function (array $a, array $b) use ($multiplier): int {
        return $multiplier * ($a['price'] <=> $b['price']);
    });

    return $products;
}
```

