### Extended Version with Validation & Direction Control

```php
<?php

/**
 * Sorts an array of products by price with optional direction.
 *
 * @param array  $products  Array of products (must contain a 'price' key)
 * @param string $direction Sort direction: 'asc' or 'desc'
 * @return array Sorted array of products
 * @throws InvalidArgumentException If direction is invalid or price key is missing
 */
function sortProductsByPrice(array $products, string $direction = 'asc'): array
{
    $direction = strtolower($direction);

    if (!in_array($direction, ['asc', 'desc'], true)) {
        throw new InvalidArgumentException("Direction must be 'asc' or 'desc'.");
    }

    // Validate that all products have a 'price' key
    foreach ($products as $index => $product) {
        if (!array_key_exists('price', $product)) {
            throw new InvalidArgumentException("Product at index {$index} is missing a 'price' key.");
        }
    }

    usort($products, function (array $a, array $b) use ($direction): int {
        $comparison = $a['price'] <=> $b['price'];

        return $direction === 'desc' ? -$comparison : $comparison;
    });

    return $products;
}

// --- Usage ---

$products = [
    ['name' => 'Laptop',     'price' => 999.99],
    ['name' => 'Mouse',      'price' => 29.99],
    ['name' => 'Keyboard',   'price' => 79.99],
    ['name' => 'Monitor',    'price' => 349.99],
    ['name' => 'Headphones', 'price' => 149.99],
];

echo "--- Ascending ---\n";
foreach (sortProductsByPrice($products, 'asc') as $product) {
    echo "{$product['name']}: \${$product['price']}\n";
}

echo "\n--- Descending ---\n";
foreach (sortProductsByPrice($products, 'desc') as $product) {
    echo "{$product['name']}: \${$product['price']}\n";
}
```

**Output:**
