function sortProductsByPriceLegacy(array $products): array
{
    usort($products, function ($productA, $productB) {
        if ($productA['price'] == $productB['price']) {
            return 0; // Prices are equal
        }
        // If price A is less than price B, return -1 (A should come first)
        // Otherwise, return 1 (B should come first)
        return ($productA['price'] < $productB['price']) ? -1 : 1;
    });

    return $products;
}

// --- Example Usage ---
$products = [
    ['name' => 'Laptop', 'price' => 1200.50],
